import React, { useRef, useState, useEffect, useContext } from 'react';
import { Link, useNavigate, useLocation } from 'react-router-dom';
import { FaCartPlus, FaSignOutAlt, FaUserAlt, FaCog } from 'react-icons/fa';
import { useAuth } from '../context/AuthContext';
import { useCart } from '../context/CartContext';
import { DarkModeContext } from '../context/DarkModeContext';
import { collection, getDocs } from 'firebase/firestore';
import { db } from '../firebaseConfig';
import { doc, getDoc } from 'firebase/firestore';
import CartPreview from './CartPreview';
import './NavBar.css';

const NavBar = () => {
  const [navbarLinks, setNavbarLinks] = useState([]);
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const [isCartPreviewOpen, setIsCartPreviewOpen] = useState(false);
  const [showStickyHeader, setShowStickyHeader] = useState(false);
  const [isMobileView, setIsMobileView] = useState(window.innerWidth <= 768);
  const [userProjects, setUserProjects] = useState([]);
  const [isSoundlegend, setIsSoundlegend] = useState(false);

  const { isDarkMode } = useContext(DarkModeContext);
  const { user, isAdmin, logout } = useAuth();
  const { cart } = useCart();
  const location = useLocation();

  const cartItemCount = Object.values(cart).reduce(
    (total, item) => total + item.quantity,
    0
  );
  const menuRef = useRef(null);
  const buttonRef = useRef(null);
  const cartRef = useRef(null);
  const navbarRef = useRef(null);
  const navigate = useNavigate();

  const fetchUserProjects = async () => {
    if (!user?.uid) return;
    try {
      const docRef = doc(db, 'users', user.uid);
      const docSnap = await getDoc(docRef);
      if (docSnap.exists()) {
        const data = docSnap.data();
        setUserProjects(data.projects || []);
        setIsSoundlegend(!!data.isSoundlegend);
      }
    } catch (err) {
      console.error('Failed to fetch user projects:', err);
    }
  };

  const filteredLinks = navbarLinks.filter((link) => {
    const access = link.access || [];
  
    if (link.enabled && access.includes('public')) return true;
    if (user && isAdmin && access.includes('admin')) return true;
    if (user && isSoundlegend && access.includes('soundlegend')) return true;
  
    return false;
  });

  useEffect(() => {
    if (user?.uid) fetchUserProjects();
  }, [user]);

  useEffect(() => {
    const observer = new IntersectionObserver(
      ([entry]) => setShowStickyHeader(!entry.isIntersecting),
      { root: null, threshold: 0 }
    );
    if (navbarRef.current) observer.observe(navbarRef.current);
    return () => observer.disconnect();
  }, []);

  useEffect(() => {
    const handleResize = () => {
      const isNowMobile = window.innerWidth <= 768;
      setIsMobileView(isNowMobile);
      if (!isNowMobile) setIsMenuOpen(false);
    };
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  useEffect(() => {
    const fetchNavbarLinks = async () => {
      try {
        const navbarLinksCollection = collection(
          db,
          'settings',
          'site',
          'navbarLinks'
        );
        const snapshot = await getDocs(navbarLinksCollection);
        const links = snapshot.docs
          .map((doc) => ({ id: doc.id, ...doc.data() }))
          .sort((a, b) => a.order - b.order);
        setNavbarLinks(links);
      } catch (err) {
        console.error('❌ Navbar fetch error:', err);
      }
    };
    fetchNavbarLinks();
  }, []);

  useEffect(() => {
    const handleClickOutside = (event) => {
      if (
        menuRef.current &&
        !menuRef.current.contains(event.target) &&
        buttonRef.current &&
        !buttonRef.current.contains(event.target)
      ) {
        setIsMenuOpen(false);
      }
      if (
        cartRef.current &&
        !cartRef.current.contains(event.target) &&
        !event.target.closest('.cart-icon')
      ) {
        setIsCartPreviewOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const handleSignOut = async () => {
    try {
      await logout();
    } catch (err) {
      console.error('Logout error:', err);
    }
  };

  const handleNavLinkClick = (path) => {
    navigate(path);
    setTimeout(() => {
      window.scrollTo({ top: 0, behavior: 'auto' });
    }, 10);
    setIsMenuOpen(false);
  };

  const isWebSticky = showStickyHeader && window.innerWidth >= 769;
  const isMobileSticky = showStickyHeader && isMobileView;

  const renderCartButton = () => (
    <button
      className="cart-icon nav-link"
      onClick={(e) => {
        e.stopPropagation();
        setIsCartPreviewOpen((prev) => !prev);
      }}
    >
      <FaCartPlus />
      <span
        className="cart-badge"
        style={{ display: cartItemCount > 0 ? 'inline-block' : 'none' }}
      >
        {cartItemCount}
      </span>
    </button>
  );

  const renderSoundLegendTab = () => {
    // console.log('🎯 renderSoundLegendTab called');
    // console.log('🧩 isSoundlegend:', isSoundlegend);
    // console.log('📦 userProjects:', userProjects);

    if (!user || !isSoundlegend || userProjects.length === 0) return null;

    return (
      <div className="nav-link dropdown">
        <span className="dropdown-label">SoundLegend ▾</span>
        <div className="dropdown-menu">
          {userProjects?.map((proj) => (
            <div
              key={proj.projectId}
              className="dropdown-item"
              onClick={(e) => {
                e.stopPropagation();
                setIsMenuOpen(false);
                navigate(`/projects/${proj.projectId}`);
              }}
            >
              {proj.projectId}
            </div>
          ))}
        </div>
      </div>
    );
  };

  return (
    <>
      {showStickyHeader && (
        <div className="navbar-sticky-wrapper">
          <div className="navbar-sticky-mini">
            <Link to="/" onClick={() => handleNavLinkClick('/')}>
              <img
                src={process.env.REACT_APP_LOGO_LIGHT}
                alt="Sticky Logo"
                className="sticky-logo-img"
              />
            </Link>

            {isMobileView ? (
              <button
                className="navbar-sticky-menu"
                onClick={() => setIsMenuOpen((prev) => !prev)}
                aria-expanded={isMenuOpen}
                aria-label="Toggle menu"
                ref={buttonRef}
              >
                <img
                  src={
                    isMenuOpen
                      ? '/menu/close-button-dark-mode.png'
                      : '/menu/menu-button-dark-mode.png'
                  }
                  alt="Menu Toggle"
                  className={`menu-arrow-icon ${isMenuOpen ? 'open' : ''}`}
                />
              </button>
            ) : (
              <div className={`navbar-links sticky-dropdown`} ref={menuRef}>
                <Link
                  to="/"
                  className="nav-link"
                  onClick={() => handleNavLinkClick('/')}
                >
                  Home
                </Link>
                {filteredLinks
                  .filter((l) => l.name.toLowerCase() !== 'home')
                  .map((link) => (
                    <Link
                      key={link.id}
                      to={`/${link.name}`}
                      className="nav-link"
                      onClick={() => handleNavLinkClick(`/${link.name}`)}
                    >
                      {link.label}
                    </Link>
                  ))}

                {renderSoundLegendTab()}
                

                {user && isAdmin && (
                  <Link
                    to="/admin"
                    className="nav-link"
                    onClick={() => handleNavLinkClick('/admin')}
                  >
                    <FaCog /> Admin
                  </Link>
                )}

                {user && (
                  <>
                    <Link
                      to="/account"
                      className="nav-link"
                      onClick={() => handleNavLinkClick('/account')}
                    >
                      <FaUserAlt /> Account
                    </Link>
                    <button
                      className="nav-link-signout"
                      onClick={handleSignOut}
                    >
                      <FaSignOutAlt /> Sign Out
                    </button>
                  </>
                )}

                {renderCartButton()}

                {isCartPreviewOpen && showStickyHeader && (
                  <div className="cart-preview-container" ref={cartRef}>
                    <CartPreview
                      onClose={() => setIsCartPreviewOpen(false)}
                      closeMenu={() => setIsMenuOpen(false)}
                    />
                  </div>
                )}
              </div>
            )}
          </div>

          {isMobileView && isMenuOpen && (
            <div className="navbar-sticky-dropdown-wrapper">
              <div className="navbar-links sticky-dropdown open" ref={menuRef}>
                <Link
                  to="/"
                  className="nav-link"
                  onClick={() => handleNavLinkClick('/')}
                >
                  Home
                </Link>
                {filteredLinks
                  .filter((l) => l.name.toLowerCase() !== 'home')
                  .map((link) => (
                    <Link
                      key={link.id}
                      to={`/${link.name}`}
                      className="nav-link"
                      onClick={() => handleNavLinkClick(`/${link.name}`)}
                    >
                      {link.label}
                    </Link>
                  ))}

                {renderSoundLegendTab()}

                {user && isAdmin && (
                  <Link
                    to="/admin"
                    className="nav-link"
                    onClick={() => handleNavLinkClick('/admin')}
                  >
                    <FaCog /> Admin
                  </Link>
                )}

                {user && (
                  <>
                    <Link
                      to="/account"
                      className="nav-link"
                      onClick={() => handleNavLinkClick('/account')}
                    >
                      <FaUserAlt /> Account
                    </Link>
                    <button
                      className="nav-link-signout"
                      onClick={handleSignOut}
                    >
                      <FaSignOutAlt /> Sign Out
                    </button>
                  </>
                )}

                {renderCartButton()}

                {isCartPreviewOpen && showStickyHeader && (
                  <div className="cart-preview-container" ref={cartRef}>
                    <CartPreview
                      onClose={() => setIsCartPreviewOpen(false)}
                      closeMenu={() => setIsMenuOpen(false)}
                    />
                  </div>
                )}
              </div>
            </div>
          )}
        </div>
      )}

      <nav className="navbar" ref={navbarRef}>
        <div className="navbar-logo">
          <Link to="/" replace onClick={() => handleNavLinkClick('/')}>
            <img
              src={
                isDarkMode
                  ? process.env.REACT_APP_LOGO_LIGHT
                  : process.env.REACT_APP_LOGO_DARK
              }
              alt="Logo"
              className="logo-img"
            />
          </Link>
        </div>

        {isMobileView && !showStickyHeader && (
          <button
            className="navbar-menu-container"
            onClick={() => setIsMenuOpen((prev) => !prev)}
            aria-expanded={isMenuOpen}
            aria-label="Toggle menu"
            ref={buttonRef}
          >
            <img
              src={
                isDarkMode
                  ? isMenuOpen
                    ? '/menu/close-button-dark-mode.png'
                    : '/menu/menu-button-dark-mode.png'
                  : isMenuOpen
                    ? '/menu/close-button-light-mode.png'
                    : '/menu/menu-button-light-mode.png'
              }
              alt="Menu Toggle"
              className={`menu-arrow-icon ${isMenuOpen ? 'open' : ''}`}
            />
          </button>
        )}

        {!showStickyHeader && (isMenuOpen || !isMobileView) && (
          <div className="navbar-links-wrapper">
            <div
              className={`navbar-links ${isMobileView && isMenuOpen ? 'open' : ''}`}
              ref={menuRef}
            >
              <Link
                to="/"
                className="nav-link"
                onClick={() => handleNavLinkClick('/')}
              >
                Home
              </Link>
              {filteredLinks
                .filter((l) => l.name.toLowerCase() !== 'home')
                .map((link) => (
                  <Link
                    key={link.id}
                    to={`/${link.name}`}
                    className="nav-link"
                    onClick={() => handleNavLinkClick(`/${link.name}`)}
                  >
                    {link.label}
                  </Link>
                ))}

              {renderSoundLegendTab()}

              {user && isAdmin && (
                <Link
                  to="/admin"
                  className="nav-link"
                  onClick={() => handleNavLinkClick('/admin')}
                >
                  <FaCog /> Admin
                </Link>
              )}

              {user && (
                <>
                  {/* Account Link removed temporarily */}
                  <button className="nav-link-signout" onClick={handleSignOut}>
                    <FaSignOutAlt /> Sign Out
                  </button>
                </>
              )}

              {renderCartButton()}

              {isCartPreviewOpen && !showStickyHeader && (
                <div className="cart-preview-container" ref={cartRef}>
                  <CartPreview
                    onClose={() => setIsCartPreviewOpen(false)}
                    closeMenu={() => setIsMenuOpen(false)}
                  />
                </div>
              )}
            </div>
          </div>
        )}
      </nav>
    </>
  );
};

export default NavBar;
